#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> v;
    v.push_back({a});
    v.push_back({b});
    v.push_back({c});

    transform(v.begin(), v.end(), v.begin(), [](int x) {
        return x * 2;
    });

    for (int x : v) {
        cout << x << endl;
    }
    return 0;
}
